import{_ as n,l as o,o as e,c as r,v as t,p as s,x as l,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"LIS 与 LCS","description":"","frontmatter":{"title":"LIS 与 LCS","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lis-lcs.md","filePath":"cs/lis-lcs.md","lastUpdated":1789023840000}'),S={name:"cs/lis-lcs.md"};function h(L,a,m,_,u,C){const i=o("Mermaid");return e(),r("div",null,[a[1]||(a[1]=t('<h1 id="lis-与-lcs" tabindex="-1">LIS 与 LCS <a class="header-anchor" href="#lis-与-lcs" aria-label="Permalink to &quot;LIS 与 LCS&quot;">​</a></h1><div class="epigraph"><p>最长上升子序列 $O(n\\log n)$ 维护最小尾；最长公共子序列 $O(nm)$ 格图，可滚动数组。</p><footer>—— 据 Fredman, On Computing the Length of Longest Increasing Subsequences, 1975；CLRS 第 15.4 节整理</footer></div><p>上一课<a href="/cs/rerooting-dp">换根 DP</a>在树上。序列回到数组。主干区间 DP 已警告 LCS 不是区间切点。缺口是 LIS 的耐心排序 / 最小尾，以及 LCS 的二维表。不重写树 DP。后课编辑距离是 LCS 的近亲。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>LIS：严格上升（或非降）最长子序列。\\(dp[i]=\\max_{j\\lt i,a_j\\lt a_i} dp[j]+1\\) 是 \\(O(n^2)\\)。维护数组 <code>tail[len]</code>：当前长度 <code>len</code> 的最小结尾。二分插入 \\(O(n\\log n)\\)。Dilworth：LIS 长度 = 最少不升链划分（点名）。</p><p>LCS：两串 \\(A,B\\)，\\(dp[i][j]\\) 来自左、上、或对角 \\(+1\\)。\\(\\Theta(nm)\\)。公共子串连续，另一转移。</p><p>缺口是这两张表，不是编辑距离（下一课）。</p><h3 id="lis-不是子数组" tabindex="-1">LIS 不是子数组 <a class="header-anchor" href="#lis-不是子数组" aria-label="Permalink to &quot;LIS 不是子数组&quot;">​</a></h3><p>子序列可跳。连续上升是滑动或差分。不要用单调队列当 LIS。</p><p><span class="marginnote">Fredman 1975。CLRS 15.4 LCS。Hunt–Szymanski 结合相等对。后课 Hirschberg 线性空间 LCS/编辑距离。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>LIS：<code>tail</code> 二分。求方案需 <code>id</code> 与前驱。LCS：二维 DP，滚动 \\(O(\\min(n,m))\\) 空间若只要长度。</p>',12)),(e(),s(p,null,{default:l(()=>[c(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%BA%8F%E5%88%97%20a%22%5D%20--%3E%20TAIL%5B%22tail%5Blen%5D%20%E6%9C%80%E5%B0%8F%E7%BB%93%E5%B0%BE%22%5D%0A%20%20AB%5B%22%E4%B8%A4%E4%B8%B2%22%5D%20--%3E%20GRID%5B%22dp%5Bi%5D%5Bj%5D%20%E6%A0%BC%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>相等元素策略决定严格与否。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p><code>tail</code> 正确：同样长度更小的结尾对后续更宽松。LCS 最优子结构在前缀对。与状压：排列的 LIS 可 \\(O(n\\log n)\\) 不必 \\(2^n\\)。与生成函数无关。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写三维 LCS。不写近似 LCS。后课默认：LIS \\(O(n\\log n)\\)；LCS \\(O(nm)\\)。下一课编辑距离与 Hirschberg。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LIS：最小尾 + 二分 \\(O(n\\log n)\\)。</li><li>LCS：前缀对 \\(O(nm)\\)。</li><li>子序列可跳，不是子数组。</li><li>出处：Fredman, 1975；CLRS 第 15.4 节。</li></ul>',7))])}const I=n(S,[["render",h]]);export{B as __pageData,I as default};
